package pages

import (
	g "maragu.dev/gomponents"
	h "maragu.dev/gomponents/html"

	"mljr-web/internal/i18n"
	hpdata "mljr-web/projects/homepage/data"
	"mljr-web/ui"
	uiform "mljr-web/ui/form"
	"mljr-web/ui/icon"
	"mljr-web/ui/layout"
	"mljr-web/ui/primitive"
	"mljr-web/ui/special"
	"mljr-web/ui/swiss"
	"mljr-web/ui/token"
)

func contactSection(p swiss.SectionProps, content hpdata.ContactContent, lang string) g.Node {
	// Submit expression: read the hidden input generated by altcha-widget into
	// a Datastar signal, then POST the contact form signals.
	submitExpr := `$altcha = document.querySelector('altcha-widget[name=altcha] input[name=altcha]')?.value || ''; $sending = true; @post('/api/contact')`
	p.Note = i18n.T(lang, "sections.contact.sub")
	p.Attrs = []g.Node{ui.Signals(`{name:'',email:'',message:'',altcha:'',sending:false,nameError:'',emailError:'',msgError:''}`)}

	currently := make([]g.Node, len(content.Currently))
	for i, c := range content.Currently {
		currently[i] = h.Li(g.Text(c))
	}
	return swiss.Section(p,
		swiss.Cell(swiss.CellProps{Variant: "block", Attrs: []g.Node{h.Class("kt-hero")}},
			swiss.Kicker("A. "+tr(lang, "Anfrage", "Enquiry"), nil),
			h.P(h.Class("kt-head"), g.Text(tr(lang, "Schreiben Sie mir.", "Write to me."))),
			h.A(h.Class("kt-mail"), h.Href("mailto:reinemic2.0@gmail.com"), g.Text("reinemic2.0@gmail.com")),
			h.P(h.Class("kt-intro"), g.Text(content.Intro)),
		),
		swiss.Cell(swiss.CellProps{Span: 3},
			swiss.Kicker("B. "+i18n.T(lang, "contact.currently"), nil),
			h.Ul(h.Class("contact-list"), g.Group(currently)),
			h.Div(h.Class("cat-links cell-foot"),
				swiss.BtnLink("https://github.com/MrCodeEU", false, []g.Node{g.Attr("target", "_blank"), g.Attr("rel", "noopener noreferrer")},
					icon.Icon("simple-icons:github", icon.Props{Size: "1em"}), g.Text("GitHub ↗")),
			),
		),
		swiss.Cell(swiss.CellProps{Span: 6},
			swiss.Kicker("C. "+tr(lang, "Formular", "Form"), g.Text(tr(lang, "Antwort per E-Mail", "Reply by email"))),
			h.Form(
				h.ID("contact-form"),
				h.Style("position:relative"),
				ui.On("submit__prevent", submitExpr),
				special.HoneypotField("_hp"),
				layout.Stack(layout.StackProps{},
					h.Div(h.Class("kt-row"), uiform.Field(uiform.FieldProps{
						Label:    i18n.T(lang, "contact.name_label"),
						ErrorFor: "name",
					}, uiform.Input(uiform.InputProps{
						Type:        "text",
						Placeholder: i18n.T(lang, "contact.name_placeholder"),
						Signal:      "name",
						Required:    true,
						Attrs:       []g.Node{g.Attr("maxlength", "100")},
					})),
						uiform.Field(uiform.FieldProps{
							Label:    i18n.T(lang, "contact.email_label"),
							ErrorFor: "email",
						}, uiform.Input(uiform.InputProps{
							Type:        "email",
							Placeholder: i18n.T(lang, "contact.email_placeholder"),
							Signal:      "email",
							Required:    true,
							Attrs:       []g.Node{g.Attr("maxlength", "254")},
						}))),
					uiform.Field(uiform.FieldProps{
						Label:    i18n.T(lang, "contact.message_label"),
						ErrorFor: "msg",
					}, uiform.Textarea(uiform.TextareaProps{
						Placeholder: i18n.T(lang, "contact.message_placeholder"),
						Signal:      "message",
						Rows:        4,
						Required:    true,
						Attrs:       []g.Node{g.Attr("minlength", "10"), g.Attr("maxlength", "5000")},
					})),
					// altcha captcha widget
					special.Captcha(special.CaptchaProps{ChallengeURL: "/api/altcha", Lazy: true}),
					// error display from server
					h.Div(h.ID("contact-error")),
					primitive.Button(primitive.ButtonProps{
						Variant: token.Primary,
						Size:    token.SizeLG,
						Type:    "submit",
						Attrs: []g.Node{
							ui.Indicator("sending"),
							g.Attr("data-attr", `{"disabled": $sending}`),
						},
					},
						h.Span(ui.Show("!$sending"), g.Text(i18n.T(lang, "contact.send")+" →")),
						h.Span(ui.Show("$sending"), g.Text(i18n.T(lang, "contact.sending"))),
					),
				),
			),
		),
	)
}

const contactCSS = `
.kt-hero { display: flex; flex-direction: column; gap: 1rem; padding-block: calc(var(--swiss-pad) * 1.5); }
.kt-head { margin: 0; font-size: clamp(3rem, 8vw, 8.5rem); font-weight: 900; letter-spacing: -0.06em; line-height: .88; }
.kt-mail { color: inherit; font-size: clamp(1.3rem, 3.2vw, 2.8rem); font-weight: 700; letter-spacing: -0.03em; text-decoration: underline; text-decoration-thickness: 3px; text-underline-offset: .18em; overflow-wrap: anywhere; }
.kt-mail:hover { text-decoration-thickness: 6px; }
.kt-intro { margin: 0; max-width: 60ch; font-size: 1.05rem; }
.kt-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sp-3); }
@media (max-width: 640px) { .kt-row { grid-template-columns: 1fr; } }
`
